set.seed(1); out <- list()
add <- function(f, args, v) out[[length(out)+1]] <<- list(f=f, args=args, v=v)
for (x in c(-40,-10,-5,-2.5,-1,-0.3,0,0.2,0.7,1.5,3,6,9,37)) add('pnorm', list(x), pnorm(x))
for (p in c(1e-300,1e-20,1e-8,0.001,0.025,0.1,0.3,0.5,0.6,0.9,0.975,0.999,1-1e-10)) add('qnorm', list(p), qnorm(p))
for (df in c(1,2.5,4,10,30,120,1000)) for (t in c(-30,-4,-2,-0.5,0.1,1,2.2,8)) add('pt', list(t,df), pt(t,df))
for (df in c(1,2.5,4,10,30,120,1000)) for (p in c(1e-10,0.005,0.025,0.1,0.6,0.975,0.9995)) add('qt', list(p,df), qt(p,df))
for (df in c(0.5,1,3,10,50,300)) for (x in c(0.001,0.5,2,7,30,100,500)) add('pchisq', list(x,df), pchisq(x,df,lower.tail=FALSE))
for (df in c(0.5,1,3,10,50,300)) for (p in c(1e-8,0.01,0.05,0.5,0.95,0.999)) add('qchisq', list(p,df), qchisq(p,df))
for (d1 in c(1,3,7.5,20)) for (d2 in c(2,10,55,1000)) for (f in c(0.01,0.8,2,5,40)) add('pf', list(f,d1,d2), pf(f,d1,d2,lower.tail=FALSE))
for (d1 in c(1,3,20)) for (d2 in c(2,10,1000)) for (p in c(0.01,0.5,0.95,0.999)) add('qf', list(p,d1,d2), qf(p,d1,d2))
for (a in c(0.3,1,2.5,20,300)) for (b in c(0.5,1,4,60)) for (x in c(1e-4,0.1,0.5,0.9,0.9999)) add('pbeta', list(x,a,b), pbeta(x,a,b))
for (a in c(0.3,1,2.5,20)) for (b in c(0.5,4,60)) for (p in c(0.001,0.2,0.5,0.97)) add('qbeta', list(p,a,b), qbeta(p,a,b))
for (n in c(5,20,137)) for (pp in c(0.01,0.3,0.5,0.93)) for (k in unique(round(c(0,1,n*pp,n/2,n-1,n)))) add('dbinom', list(k,n,pp), dbinom(k,n,pp))
for (k in 0:6) add('dhyper', list(k,7,9,6), dhyper(k,7,9,6))
for (df in c(3,10,40)) for (ncp in c(0.5,2,4)) for (t in c(-1,0.5,2,4,8)) add('pnt', list(t,df,ncp), pt(t,df,ncp))
for (d1 in c(2,4)) for (d2 in c(10,60)) for (ncp in c(1,5,15)) for (f in c(0.5,2,4)) add('pnf', list(f,d1,d2,ncp), pf(f,d1,d2,ncp,lower.tail=FALSE))
for (df in c(1,4)) for (ncp in c(1,10)) for (x in c(1,5,20)) add('pnchisq', list(x,df,ncp), pchisq(x,df,ncp))
for (k in c(2,3,5,10)) for (df in c(3,10,40,1e6)) for (q in c(1,2.5,4,6)) add('ptukey', list(q,1,k,df), ptukey(q,k,df))
for (k in c(2,3,5,10)) for (df in c(3,10,40)) for (p in c(0.9,0.95,0.99)) add('qtukey', list(p,1,k,df), qtukey(p,k,df))
for (x in c(0.1,0.5,1,3.5,10,50,171.3)) add('lgamma', list(x), lgamma(x))
for (a in c(0.5,2,10,100)) for (x in c(0.1,1,5,50,150)) add('pgamma', list(x,a), pgamma(x,a))
for (x in c(0,1,3,10)) for (s in c(0.5,2,40)) for (mu in c(0.4,3,25)) add('dnbinomMu', list(x,s,mu), dnbinom(x,size=s,mu=mu))
for (x in c(0,2,7,40)) for (l in c(0.3,4,30)) add('ppois', list(x,l), ppois(x,l))
add('padjust_holm', list(c(0.01,0.04,0.03,0.2,0.005)), p.adjust(c(0.01,0.04,0.03,0.2,0.005),'holm'))
add('padjust_hommel', list(c(0.01,0.04,0.03,0.2,0.005)), p.adjust(c(0.01,0.04,0.03,0.2,0.005),'hommel'))
add('padjust_BY', list(c(0.01,0.04,0.03,0.2,0.005)), p.adjust(c(0.01,0.04,0.03,0.2,0.005),'BY'))
add('padjust_hochberg', list(c(0.01,0.04,0.03,0.2,0.005)), p.adjust(c(0.01,0.04,0.03,0.2,0.005),'hochberg'))
add('padjust_BH', list(c(0.01,0.04,0.03,0.2,0.005)), p.adjust(c(0.01,0.04,0.03,0.2,0.005),'BH'))
f <- function(x) x^3 - 2*x - 5; add('uniroot', list(), uniroot(f, c(2,3))$root)
f2 <- function(n) pwr::pwr.t.test(n=n,d=0.5)$power - 0.8; add('uniroot2', list(), uniroot(f2, c(2+1e-10, 1e9))$root)
writeLines(jsonlite::toJSON(out, auto_unbox=TRUE, digits=NA), 'tests/engine/dist-ref.json')
